from pathlib import Path
import base64

layout_path = Path("app/(portal)/layout.tsx")
css_path = Path("components/sepulchria/sep-ui-unified.css")
manager_path = Path("components/portal/portal-modal-viewport-manager.tsx")

if not layout_path.exists():
    raise SystemExit("Missing app/(portal)/layout.tsx. No files changed.")

if not css_path.exists():
    raise SystemExit(
        "Missing components/sepulchria/sep-ui-unified.css. "
        "Apply the successful unification patch first. No files changed."
    )

layout = layout_path.read_text(encoding="utf-8")
css = css_path.read_text(encoding="utf-8")

# ------------------------------------------------------------------
# 1. Fix the ugly/pale modal border in the existing unified CSS.
# ------------------------------------------------------------------
old_modal_border = """  --sep-unified-modal-border:
      color-mix(in srgb, rgb(var(--sep-colour-795a34)) 70%, transparent);"""

new_modal_border = """  --sep-unified-modal-border:
      var(--sep-unified-control-border);"""

if old_modal_border in css:
    css = css.replace(
        old_modal_border,
        new_modal_border,
        1,
    )

# Also replace the non-@supports fallback modal token when present.
css = css.replace(
    "--sep-unified-modal-border: rgba(var(--sep-rgb-121-90-52), 0.70);",
    "--sep-unified-modal-border: var(--sep-unified-control-border);",
)

# ------------------------------------------------------------------
# 2. Add the central modal viewport manager.
# ------------------------------------------------------------------
manager_path.write_text(
    base64.b64decode("").decode("utf-8"),
    encoding="utf-8",
)

import_line = (
    'import { PortalModalViewportManager } '
    'from "@/components/portal/portal-modal-viewport-manager";'
)

if import_line not in layout:
    anchor = (
        'import { PortalResponsiveRightSidebar } '
        'from "@/components/portal/portal-responsive-right-sidebar";'
    )

    if anchor not in layout:
        raise SystemExit(
            "Could not find the expected Portal layout import anchor. "
            "No layout changes were written."
        )

    layout = layout.replace(
        anchor,
        anchor + "\n" + import_line,
        1,
    )

mount = "            <PortalModalViewportManager />"

if mount not in layout:
    anchor = "            <PortalSessionGuard />"

    if anchor not in layout:
        raise SystemExit(
            "Could not find PortalSessionGuard mount anchor. "
            "No layout changes were written."
        )

    layout = layout.replace(
        anchor,
        anchor + "\n\n" + mount,
        1,
    )

# ------------------------------------------------------------------
# 3. Append modal-specific CSS exactly once.
# ------------------------------------------------------------------
marker = "PORTAL MODALS — UNIFIED BORDER + MAXIMIZE / RESTORE"
addition = base64.b64decode("").decode("utf-8")

if marker not in css:
    css = css + addition

layout_path.write_text(layout, encoding="utf-8")
css_path.write_text(css, encoding="utf-8")

print("SUCCESS")
print("")
print("Portal modal standardisation applied.")
print("")
print("Changed/created:")
print("  app/(portal)/layout.tsx")
print("  components/sepulchria/sep-ui-unified.css")
print("  components/portal/portal-modal-viewport-manager.tsx")
print("")
print("Behaviour:")
print("  - actual semantic portal modals open maximized")
print("  - modal frame border now matches unified button border")
print("  - maximize/restore control is added centrally")
print("  - placed after Minimize when present, otherwise before Close")
print("  - restore returns to original size")
print("  - after manual resize, maximize remembers resized dimensions")
print("  - existing modal close/minimize/business logic is untouched")
print("")
print("Run: npm run build")
